// Regenerates src/sde/wormhole-statics.ts from the WormholeSystems static data (MIT licensed).
// Usage: node scripts/update-wormhole-statics.mjs [git ref, default main]
import { writeFileSync } from "node:fs";

const REPO = "WormholeSystems/WormholeSystems";
const FILE = "data/static/wormhole_systems.json";
let ref = process.argv[2] ?? "main";
if (!/^[0-9a-f]{40}$/.test(ref)) {
  // Pin the generated file to a commit so the provenance is exact.
  const res = await fetch(`https://api.github.com/repos/${REPO}/commits?path=${FILE}&sha=${ref}&per_page=1`);
  ref = (await res.json())[0].sha;
}
const res = await fetch(`https://raw.githubusercontent.com/${REPO}/${ref}/${FILE}`);
if (!res.ok) throw new Error(`HTTP ${res.status}`);
const { systems } = await res.json();

const rows = systems
  .filter((s) => s.id >= 31000000 && s.id < 32000000 && s.statics?.length)
  .sort((a, b) => a.id - b.id)
  .map((s) => {
    for (const c of s.statics) if (!/^[A-Z]\d{3}$/.test(c)) throw new Error(`Bad wormhole code ${c} in ${s.name}`);
    return `  ${s.id}: "${s.statics.join(" ")}",`;
  });

const out = `// Generated by scripts/update-wormhole-statics.mjs - do not edit by hand.
// Source: https://github.com/${REPO}/blob/${ref}/${FILE}
// Copyright (c) 2026 WormholeSystems, MIT License. The SDE does not list wormhole statics.

/** Static wormhole codes per J-space solar system id, space separated. */
export const WORMHOLE_STATICS: Record<number, string> = {
${rows.join("\n")}
};
`;
const dest = new URL("../src/sde/wormhole-statics.ts", import.meta.url);
writeFileSync(dest, out);
console.log(`Wrote ${rows.length} systems from ${REPO}@${ref.slice(0, 12)}`);
